// Research reports and literature review (ADR-004). research.json is generated by pipeline/reports.py from the
// analysis outputs; every number in it was filled in by the generator, not typed.

import { fetchJson } from "./binpack";

export type Block =
  | { t: "h"; level: 2 | 3; text: string }
  | { t: "p"; text: string }
  | { t: "ul" | "ol"; items: string[] }
  | { t: "table"; head: string[]; rows: string[][]; caption?: string }
  | { t: "quote"; text: string; cite?: string }
  | { t: "note"; text: string };

export interface Report {
  slug: string;
  title: string;
  summary: string;
  kind: "study" | "literature";
  blocks: Block[];
}

export interface Reference {
  id: string;
  authors: string;
  year: number;
  title: string;
  venue: string;
  url: string;
  thread: string;
  takeaway: string;
  verified: string; // how the citation was checked (e.g. "arXiv API 2026-11-03")
}

export interface ResearchData {
  generated: string;
  reports: Report[];
  references: Reference[];
}

const str = (x: unknown, max = 4000) => (typeof x === "string" ? x.slice(0, max) : "");
const SLUG = /^[a-z0-9-]{1,64}$/;

function block(raw: unknown): Block | null {
  if (!raw || typeof raw !== "object") return null;
  const b = raw as Record<string, unknown>;
  switch (b.t) {
    case "h": return { t: "h", level: b.level === 3 ? 3 : 2, text: str(b.text, 200) };
    case "p": return { t: "p", text: str(b.text) };
    case "note": return { t: "note", text: str(b.text) };
    case "quote": return { t: "quote", text: str(b.text, 1000), cite: str(b.cite, 300) || undefined };
    case "ul": case "ol":
      return Array.isArray(b.items) ? { t: b.t, items: b.items.slice(0, 60).map((i) => str(i, 1500)) } : null;
    case "table": {
      if (!Array.isArray(b.head) || !Array.isArray(b.rows)) return null;
      const head = b.head.slice(0, 12).map((h) => str(h, 120));
      const rows = b.rows.slice(0, 200).filter(Array.isArray).map((r) => (r as unknown[]).slice(0, head.length).map((c) => str(String(c ?? ""), 300)));
      return { t: "table", head, rows, caption: str(b.caption, 300) || undefined };
    }
    default: return null;
  }
}

export function sanitizeResearch(raw: unknown): ResearchData {
  if (!raw || typeof raw !== "object") throw new Error("research.json is not an object");
  const r = raw as Record<string, unknown>;
  if (!Array.isArray(r.reports)) throw new Error("research.json has no reports");
  const reports: Report[] = [];
  for (const x of r.reports as Record<string, unknown>[]) {
    if (!x || typeof x.slug !== "string" || !SLUG.test(x.slug) || !Array.isArray(x.blocks)) continue;
    reports.push({
      slug: x.slug, title: str(x.title, 160), summary: str(x.summary, 600),
      kind: x.kind === "literature" ? "literature" : "study",
      blocks: (x.blocks as unknown[]).map(block).filter((b): b is Block => !!b),
    });
  }
  const references: Reference[] = [];
  for (const x of (Array.isArray(r.references) ? r.references : []) as Record<string, unknown>[]) {
    if (!x || typeof x.id !== "string" || !SLUG.test(x.id)) continue;
    const url = str(x.url, 300);
    references.push({
      id: x.id, authors: str(x.authors, 300), year: Number.isInteger(x.year) ? (x.year as number) : 0, title: str(x.title, 300),
      venue: str(x.venue, 160), url: /^https:\/\//.test(url) ? url : "", thread: str(x.thread, 80), takeaway: str(x.takeaway, 900),
      verified: str(x.verified, 120),
    });
  }
  return { generated: str(r.generated, 40), reports, references };
}

export async function loadResearch(dataBase: string): Promise<ResearchData> {
  return sanitizeResearch(await fetchJson<unknown>(`${dataBase}/research.json`));
}

/** Inline markdown subset: **bold**, *em*, `code`, [text](https://… | #/…), [@ref-id]. */
export type Inline =
  | { k: "text"; v: string }
  | { k: "b" | "i" | "code"; v: string }
  | { k: "a"; v: string; href: string }
  | { k: "cite"; id: string };

const INLINE = /\*\*([^*]+)\*\*|\*([^*]+)\*|`([^`]+)`|\[@([a-z0-9-]+)\]|\[([^\]]+)\]\(((?:https:\/\/|#\/)[^)\s]+)\)/g;

export function parseInline(s: string): Inline[] {
  const out: Inline[] = [];
  let last = 0;
  for (const m of s.matchAll(INLINE)) {
    if (m.index! > last) out.push({ k: "text", v: s.slice(last, m.index) });
    if (m[1]) out.push({ k: "b", v: m[1] });
    else if (m[2]) out.push({ k: "i", v: m[2] });
    else if (m[3]) out.push({ k: "code", v: m[3] });
    else if (m[4]) out.push({ k: "cite", id: m[4] });
    else out.push({ k: "a", v: m[5], href: m[6] });
    last = m.index! + m[0].length;
  }
  if (last < s.length) out.push({ k: "text", v: s.slice(last) });
  return out;
}
